INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Gilt die DSGVO nur für Unternehmen in Deutschland?', 2, '[{"text": "Nein", "correct": true, "because": "EU-weit und darüber hinaus"}, {"text": "Ja", "correct": false, "because": "Nicht auf Deutschland beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt die DSGVO?', 3, '[{"text": "Schutz personenbezogener Daten", "correct": true, "because": "Datenschutz stärken"}, {"text": "Netzwerkgeschwindigkeit erhöhen", "correct": false, "because": "Kein technisches Ziel"}, {"text": "Hardware optimieren", "correct": false, "because": "Nicht Hardware-bezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte gewährt die DSGVO den Betroffenen?', 5, '[{"text": "Recht auf Auskunft", "correct": true, "because": "Daten Einsicht"}, {"text": "Recht auf Löschung", "correct": true, "because": "Vergessenwerden"}, {"text": "Recht auf kostenlose Software", "correct": false, "because": "Kein DSGVO-Recht"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die DSGVO schützt personenbezogene Daten. b) Sie gilt nur für große Unternehmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle Unternehmen betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Umsetzung der DSGVO?', 4, '[{"text": "Datensicherheit", "correct": false, "because": "Schutzmaßnahmen nötig"}, {"text": "Einwilligung", "correct": false, "because": "Rechtsgrundlage wichtig"}, {"text": "Papierfarbe", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die DSGVO seit 2018 gilt?', 2, '[{"text": "Ja", "correct": true, "because": "25. Mai 2018"}, {"text": "Nein", "correct": false, "because": "Seit 2018 in Kraft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten fallen unter die DSGVO?', 3, '[{"text": "Personenbezogene Daten", "correct": true, "because": "Name, Adresse etc."}, {"text": "Öffentliche Netzwerkdaten", "correct": false, "because": "Nicht spezifisch"}, {"text": "Hardware-Logs", "correct": false, "because": "Nur bei Personenbezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten legt die DSGVO Unternehmen auf?', 5, '[{"text": "Datenschutzbeauftragter", "correct": true, "because": "Bei Bedarf"}, {"text": "Datenverarbeitungsverzeichnis", "correct": true, "because": "Dokumentation"}, {"text": "Kostenlose Software", "correct": false, "because": "Kein DSGVO-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Die DSGVO fordert Transparenz. b) Sie verbietet Datenverarbeitung. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verarbeitung erlaubt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die DSGVO-Umsetzung?', 4, '[{"text": "Datenschutzrichtlinien", "correct": false, "because": "Pflicht"}, {"text": "Technische Maßnahmen", "correct": false, "because": "Schutz nötig"}, {"text": "Papierarchiv", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Gilt die DSGVO auch für Nicht-EU-Unternehmen?', 2, '[{"text": "Ja", "correct": true, "because": "Bei EU-Daten"}, {"text": "Nein", "correct": false, "because": "Extraterritoriale Wirkung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen fordert die DSGVO?', 4, '[{"text": "Datensparsamkeit", "correct": true, "because": "Nur nötige Daten"}, {"text": "Datenschutz durch Technik", "correct": true, "because": "Privacy by Design"}, {"text": "Papierdokumentation", "correct": false, "because": "Nicht vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die DSGVO keine Strafen vorsieht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Bis zu 20 Mio. Euro"}, {"text": "Ja", "correct": false, "because": "Hohe Geldstrafen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der DSGVO?', 3, '[{"text": "Datenschutz", "correct": true, "because": "Kernanliegen"}, {"text": "Schnelligkeit", "correct": false, "because": "Sicherheit zählt"}, {"text": "Papierformate", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die DSGVO verlangt Einwilligung. b) Sie gilt nur für digitale Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch physische Daten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen hat ein DSGVO-Verstoß?', 5, '[{"text": "Geldstrafen", "correct": true, "because": "Bis 20 Mio. Euro"}, {"text": "Verbote", "correct": true, "because": "Verarbeitung einschränken"}, {"text": "Hardware-Upgrade", "correct": false, "because": "Kein DSGVO-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der DSGVO unwichtig?', 3, '[{"text": "Datensicherheit", "correct": false, "because": "Pflicht"}, {"text": "Transparenz", "correct": false, "because": "Kernprinzip"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss jede Firma einen Datenschutzbeauftragten haben?', 3, '[{"text": "Nein", "correct": true, "because": "Abhängig von Größe"}, {"text": "Ja", "correct": false, "because": "Nur bei Bedarf"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die DSGVO Datenexport regelt?', 2, '[{"text": "Ja", "correct": true, "because": "Drittland-Übermittlung"}, {"text": "Nein", "correct": false, "because": "Regelung enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip ist für die DSGVO zentral?', 4, '[{"text": "Datenschutz durch Technik", "correct": true, "because": "Privacy by Design"}, {"text": "Manuelle Dateneingabe", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Papierarchivierung", "correct": false, "because": "Digital im Fokus"}]');
